        "sl": 446,
        "name": "",
        "comp_val": "ENROFLOXACIN",
        "pack": "during bacterial growth and reproduction. Binding of the quinolone to both the enzyme and the DNA to form a ternary complex inhibits the rejoining step and can cause cell death by inducing cleavage of the DNA. Indications: CRD, CCRD, colibacillosis, salmonellosis. Infectious coryza, dermatitis, ascites, gout. Gram positive and gram negative bacterial infections Contraindication: See under fluroquinolones Side effect: See under fluroquinolones Precaution: See under fluroquinolones Doses and administration: For treatment: 20 mg/kg body weight for 3-5 days. Or as directed by the registered Veterinarian. Withdrawal period: Meat: 4 days, Egg: 7 days, Milk: Not required.",
