        "pack": "is a sulfonamide antibacterial. Chemically, it is an organic compound consisting of an aniline derivatized with a sulfonamide group. As a sulfonamide antibiotic, sulfanilamide functions by competitively inhibiting (that is, by acting as a substrate analogue) enzymatic reactions",
