        "comp_val": "BDNVF proprietary preparation (generic context not resolved)",
        "pack": "calcium-D-pentothenate, innocitol, DL-Methionine Indication: Ruminants: Inappetance, weakness, ataxia, paresis, anorexia, diarrhea followed by signs characteristic of polyuencephalomalacia including blindness, head pressing, convulsion, paralysis, opisthotonos, poor growth, loss of hair, skin lessions, lacrimation & salivation, scours, metabolic disorders. Horse: Letargy, anorexia, weight loss, ataxia cardiac arrhythmias, muscle tremors & convulsions. Dogs: Anorexia, emesis, depression, paraparesis, torticollis, circling, convulsions, signs of Black tongue, cheilosis, glossitis, gingivitis, bloody diarrhea and cardiomyopathy. Contraindications: Injection should not be used in animals hypersensitive to active ingredient. Side Effect: Injection has not common side effect for recommended dosage.",
